using System.Runtime.CompilerServices;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.Diagnostics;
using MinimalCleanArch.Audit.Configuration;
using MinimalCleanArch.Audit.Entities;
using MinimalCleanArch.Audit.Services;
using MinimalCleanArch.Domain.Entities;

namespace MinimalCleanArch.Audit.Interceptors;

/// <summary>
/// EF Core interceptor that captures entity changes and creates audit log entries,
/// including entities whose primary keys are generated by the database on insert.
/// </summary>
public class AuditSaveChangesInterceptor : SaveChangesInterceptor
{
    private readonly IAuditContextProvider _contextProvider;
    private readonly AuditOptions _options;
    private readonly TimeProvider _timeProvider;
    private readonly JsonSerializerOptions _jsonOptions;
    private readonly ConditionalWeakTable<DbContext, List<AuditEntry>> _pendingTemporaryEntries = new();

    /// <summary>
    /// Initializes a new instance of the <see cref="AuditSaveChangesInterceptor"/> class.
    /// </summary>
    /// <param name="contextProvider">The audit context provider.</param>
    /// <param name="options">The audit options.</param>
    /// <param name="timeProvider">Optional time provider for deterministic audit timestamps.</param>
    public AuditSaveChangesInterceptor(
        IAuditContextProvider contextProvider,
        AuditOptions options,
        TimeProvider? timeProvider = null)
    {
        _contextProvider = contextProvider ?? throw new ArgumentNullException(nameof(contextProvider));
        _options = options ?? throw new ArgumentNullException(nameof(options));
        _timeProvider = timeProvider ?? TimeProvider.System;
        _jsonOptions = new JsonSerializerOptions
        {
            WriteIndented = false,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull
        };
    }

    /// <inheritdoc />
    public override async ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData eventData,
        InterceptionResult<int> result,
        CancellationToken cancellationToken = default)
    {
        if (!_options.Enabled || eventData.Context == null)
            return await base.SavingChangesAsync(eventData, result, cancellationToken);

        PrepareAuditEntries(eventData.Context);

        return await base.SavingChangesAsync(eventData, result, cancellationToken);
    }

    /// <inheritdoc />
    public override InterceptionResult<int> SavingChanges(
        DbContextEventData eventData,
        InterceptionResult<int> result)
    {
        if (!_options.Enabled || eventData.Context == null)
            return base.SavingChanges(eventData, result);

        PrepareAuditEntries(eventData.Context);

        return base.SavingChanges(eventData, result);
    }

    /// <inheritdoc />
    public override async ValueTask<int> SavedChangesAsync(
        SaveChangesCompletedEventData eventData,
        int result,
        CancellationToken cancellationToken = default)
    {
        if (eventData.Context != null)
        {
            await ProcessTemporaryPropertiesAsync(eventData.Context, cancellationToken);
        }

        return await base.SavedChangesAsync(eventData, result, cancellationToken);
    }

    /// <inheritdoc />
    public override int SavedChanges(
        SaveChangesCompletedEventData eventData,
        int result)
    {
        if (eventData.Context != null)
        {
            ProcessTemporaryProperties(eventData.Context);
        }

        return base.SavedChanges(eventData, result);
    }

    /// <inheritdoc />
    public override Task SaveChangesFailedAsync(
        DbContextErrorEventData eventData,
        CancellationToken cancellationToken = default)
    {
        if (eventData.Context != null)
        {
            _pendingTemporaryEntries.Remove(eventData.Context);
        }

        return base.SaveChangesFailedAsync(eventData, cancellationToken);
    }

    /// <inheritdoc />
    public override void SaveChangesFailed(DbContextErrorEventData eventData)
    {
        if (eventData.Context != null)
        {
            _pendingTemporaryEntries.Remove(eventData.Context);
        }

        base.SaveChangesFailed(eventData);
    }

    private void PrepareAuditEntries(DbContext context)
    {
        var auditEntries = CreateAuditEntries(context);
        if (auditEntries.Count == 0)
        {
            return;
        }

        var immediateEntries = auditEntries.Where(e => !e.HasTemporaryProperties).ToList();
        var temporaryEntries = auditEntries.Where(e => e.HasTemporaryProperties).ToList();

        if (immediateEntries.Count > 0)
        {
            var previousAutoDetect = context.ChangeTracker.AutoDetectChangesEnabled;
            context.ChangeTracker.AutoDetectChangesEnabled = false;
            try
            {
                foreach (var entry in immediateEntries)
                {
                    context.Set<AuditLog>().Add(entry.ToAuditLog(_jsonOptions, _options.MaxValueLength));
                }
            }
            finally
            {
                context.ChangeTracker.AutoDetectChangesEnabled = previousAutoDetect;
            }
        }

        if (temporaryEntries.Count > 0)
        {
            var list = _pendingTemporaryEntries.GetOrCreateValue(context);
            list.AddRange(temporaryEntries);
        }
    }

    private List<AuditEntry> CreateAuditEntries(DbContext context)
    {
        var entries = new List<AuditEntry>();
        var timestamp = _timeProvider.GetUtcNow().UtcDateTime;

        foreach (var entry in context.ChangeTracker.Entries())
        {
            if (ShouldSkipEntry(entry))
                continue;

            var auditEntry = CreateAuditEntry(entry, timestamp);
            if (auditEntry != null)
            {
                entries.Add(auditEntry);
            }
        }

        return entries;
    }

    private bool ShouldSkipEntry(EntityEntry entry)
    {
        // Skip AuditLog itself
        if (entry.Entity is AuditLog)
            return true;

        // Skip unchanged entries
        if (entry.State == EntityState.Unchanged || entry.State == EntityState.Detached)
            return true;

        // Skip excluded entity types
        var entityTypeName = entry.Entity.GetType().FullName ?? entry.Entity.GetType().Name;
        if (_options.ExcludedEntityTypes.Contains(entityTypeName))
            return true;

        return false;
    }

    private AuditEntry? CreateAuditEntry(EntityEntry entry, DateTime timestamp)
    {
        var auditEntry = new AuditEntry
        {
            EntityType = entry.Entity.GetType().Name,
            Timestamp = timestamp,
            UserId = _contextProvider.GetUserId(),
            UserName = _contextProvider.GetUserName(),
            TenantId = _contextProvider.GetTenantId(),
            CorrelationId = _contextProvider.GetCorrelationId(),
            CaptureNewValues = _options.CaptureNewValues
        };

        if (_options.CaptureClientIp)
            auditEntry.ClientIpAddress = _contextProvider.GetClientIpAddress();

        if (_options.CaptureUserAgent)
            auditEntry.UserAgent = _contextProvider.GetUserAgent();

        var metadata = _contextProvider.GetMetadata();
        if (metadata != null && metadata.Count > 0)
        {
            auditEntry.Metadata = JsonSerializer.Serialize(metadata, _jsonOptions);
        }

        // Capture primary key properties and any store-generated temporary properties (deduplicated by metadata)
        var keyParts = new List<string>();
        var seenTempNames = new HashSet<string>(StringComparer.Ordinal);

        foreach (var property in entry.Properties)
        {
            if (property.IsTemporary)
            {
                if (seenTempNames.Add(property.Metadata.Name))
                {
                    auditEntry.TemporaryProperties.Add(property);
                }
            }
            else if (property.Metadata.IsPrimaryKey())
            {
                keyParts.Add(property.CurrentValue?.ToString() ?? string.Empty);
            }
        }

        auditEntry.EntityId = string.Join(",", keyParts);

        // Determine operation and capture values
        switch (entry.State)
        {
            case EntityState.Added:
                auditEntry.Operation = AuditOperation.Create;
                if (_options.CaptureNewValues)
                {
                    auditEntry.CapturedNewValues = CaptureValuesDictionary(entry, e => e.CurrentValue);
                }
                break;

            case EntityState.Deleted:
                auditEntry.Operation = AuditOperation.Delete;
                if (_options.CaptureOldValues)
                {
                    auditEntry.OldValues = CaptureValues(entry, e => e.OriginalValue);
                }
                break;

            case EntityState.Modified:
                // Check if this is a soft delete
                if (entry.Entity is ISoftDelete)
                {
                    var isDeletedProp = entry.Property(nameof(ISoftDelete.IsDeleted));
                    if (isDeletedProp.IsModified)
                    {
                        var wasDeleted = (bool)(isDeletedProp.OriginalValue ?? false);
                        var isDeleted = (bool)(isDeletedProp.CurrentValue ?? false);

                        if (!wasDeleted && isDeleted)
                        {
                            auditEntry.Operation = AuditOperation.SoftDelete;
                        }
                        else if (wasDeleted && !isDeleted)
                        {
                            auditEntry.Operation = AuditOperation.Restore;
                        }
                        else
                        {
                            auditEntry.Operation = AuditOperation.Update;
                        }
                    }
                    else
                    {
                        auditEntry.Operation = AuditOperation.Update;
                    }
                }
                else
                {
                    auditEntry.Operation = AuditOperation.Update;
                }

                var modifiedProperties = entry.Properties
                    .Where(p => p.IsModified && !_options.ExcludedProperties.Contains(p.Metadata.Name))
                    .ToList();

                if (_options.CaptureOldValues)
                {
                    auditEntry.OldValues = CaptureModifiedValues(modifiedProperties, p => p.OriginalValue);
                }

                if (_options.CaptureNewValues)
                {
                    auditEntry.NewValues = CaptureModifiedValues(modifiedProperties, p => p.CurrentValue);
                }

                if (_options.TrackChangedProperties)
                {
                    auditEntry.ChangedProperties = JsonSerializer.Serialize(
                        modifiedProperties.Select(p => p.Metadata.Name).ToList(),
                        _jsonOptions);
                }
                break;

            default:
                return null;
        }

        return auditEntry;
    }

    private Dictionary<string, object?> CaptureValuesDictionary(EntityEntry entry, Func<PropertyEntry, object?> valueSelector)
    {
        var values = new Dictionary<string, object?>();

        foreach (var property in entry.Properties)
        {
            if (_options.ExcludedProperties.Contains(property.Metadata.Name))
                continue;

            if (property.IsTemporary)
                continue;

            values[property.Metadata.Name] = valueSelector(property);
        }

        return values;
    }

    private string? CaptureValues(EntityEntry entry, Func<PropertyEntry, object?> valueSelector)
    {
        var values = CaptureValuesDictionary(entry, valueSelector);
        if (values.Count == 0)
            return null;

        var json = JsonSerializer.Serialize(values, _jsonOptions);
        return TruncateIfNeeded(json, _options.MaxValueLength);
    }

    private string? CaptureModifiedValues(
        List<PropertyEntry> properties,
        Func<PropertyEntry, object?> valueSelector)
    {
        if (properties.Count == 0)
            return null;

        var values = new Dictionary<string, object?>();

        foreach (var property in properties)
        {
            values[property.Metadata.Name] = valueSelector(property);
        }

        var json = JsonSerializer.Serialize(values, _jsonOptions);
        return TruncateIfNeeded(json, _options.MaxValueLength);
    }

    internal static string TruncateIfNeeded(string value, int maxLength)
    {
        if (value.Length <= maxLength)
            return value;

        return value[..maxLength] + "...[truncated]";
    }

    private async Task ProcessTemporaryPropertiesAsync(DbContext context, CancellationToken cancellationToken)
    {
        if (!_pendingTemporaryEntries.TryGetValue(context, out var pendingEntries) || pendingEntries.Count == 0)
        {
            return;
        }

        // Remove before saving audit logs to guarantee no infinite recursion
        _pendingTemporaryEntries.Remove(context);

        foreach (var entry in pendingEntries)
        {
            context.Set<AuditLog>().Add(entry.ToAuditLog(_jsonOptions, _options.MaxValueLength, _options.ExcludedProperties));
        }

        await context.SaveChangesAsync(cancellationToken);
    }

    private void ProcessTemporaryProperties(DbContext context)
    {
        if (!_pendingTemporaryEntries.TryGetValue(context, out var pendingEntries) || pendingEntries.Count == 0)
        {
            return;
        }

        _pendingTemporaryEntries.Remove(context);

        foreach (var entry in pendingEntries)
        {
            context.Set<AuditLog>().Add(entry.ToAuditLog(_jsonOptions, _options.MaxValueLength, _options.ExcludedProperties));
        }

        context.SaveChanges();
    }
}

/// <summary>
/// Internal class to track audit entry before converting to AuditLog entity.
/// </summary>
internal sealed class AuditEntry
{
    public string EntityType { get; set; } = string.Empty;
    public string EntityId { get; set; } = string.Empty;
    public AuditOperation Operation { get; set; }
    public DateTime Timestamp { get; set; }
    public string? UserId { get; set; }
    public string? UserName { get; set; }
    public string? TenantId { get; set; }
    public string? CorrelationId { get; set; }
    public string? ClientIpAddress { get; set; }
    public string? UserAgent { get; set; }
    public string? OldValues { get; set; }
    public string? NewValues { get; set; }
    public string? ChangedProperties { get; set; }
    public string? Metadata { get; set; }
    public bool CaptureNewValues { get; set; }
    public Dictionary<string, object?>? CapturedNewValues { get; set; }

    public List<PropertyEntry> TemporaryProperties { get; } = new();
    public bool HasTemporaryProperties => TemporaryProperties.Count > 0;

    public AuditLog ToAuditLog(
        JsonSerializerOptions jsonOptions,
        int maxValueLength,
        HashSet<string>? excludedProperties = null)
    {
        if (HasTemporaryProperties)
        {
            var pkValues = new List<string>();
            foreach (var prop in TemporaryProperties)
            {
                if (prop.Metadata.IsPrimaryKey())
                {
                    pkValues.Add(prop.CurrentValue?.ToString() ?? string.Empty);
                }

                if (CaptureNewValues &&
                    CapturedNewValues is not null &&
                    (excludedProperties is null || !excludedProperties.Contains(prop.Metadata.Name)))
                {
                    CapturedNewValues[prop.Metadata.Name] = prop.CurrentValue;
                }
            }

            if (pkValues.Count > 0)
            {
                EntityId = string.IsNullOrEmpty(EntityId)
                    ? string.Join(",", pkValues)
                    : $"{EntityId},{string.Join(",", pkValues)}";
            }
        }

        if (CaptureNewValues && CapturedNewValues is { Count: > 0 })
        {
            var json = JsonSerializer.Serialize(CapturedNewValues, jsonOptions);
            NewValues = AuditSaveChangesInterceptor.TruncateIfNeeded(json, maxValueLength);
        }

        return new AuditLog
        {
            EntityType = EntityType,
            EntityId = EntityId,
            Operation = Operation,
            Timestamp = Timestamp,
            UserId = UserId,
            UserName = UserName,
            TenantId = TenantId,
            CorrelationId = CorrelationId,
            ClientIpAddress = ClientIpAddress,
            UserAgent = UserAgent,
            OldValues = OldValues,
            NewValues = NewValues,
            ChangedProperties = ChangedProperties,
            Metadata = Metadata
        };
    }
}
